 try{for(let i=0;i<localStorage.length;i++){const key=localStorage.key(i);if(key?.startsWith(prefix)){const raw=localStorage.getItem(key);if(raw)out[key.slice(prefix.length)]=JSON.parse(raw);}}}catch{}
